def _sanitize_dates(dates: dict) -> dict:
    """Coerce per-date flight info so it conforms to tau2's strict schema.

    Remap/drop cabin keys in prices and available_seats that are outside
    the tau2 cabin vocabulary.
    """
    clean: dict = {}
    for date_key, info in dates.items():
        if not isinstance(info, dict):
            clean[date_key] = info
            continue
        info = dict(info)  # shallow copy
        for field in ("prices", "available_seats"):
            raw = info.get(field)
            if not isinstance(raw, dict):
                continue
            coerced: dict = {}
            for cabin, val in raw.items():
                if cabin in _TAU2_CABINS:
                    coerced[cabin] = val
                elif cabin in _CABIN_COERCE:
                    target = _CABIN_COERCE[cabin]
                    coerced.setdefault(target, val)
                # else: drop unknown cabin silently
            # Ensure all three tau2 cabins present
            for c in _TAU2_CABINS:
                coerced.setdefault(c, 0)
            info[field] = coerced
        clean[date_key] = info
    return clean


